          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "issueNumber": {
                "type": "integer"
              },
              "commentIds": {
                "type": "array",
                "items": {
                  "type": "integer"
                }
              },
              "disposition": {
                "type": "string"
              },
              "draftText": {
                "type": "string"
              },
              "rationale": {
                "type": "string"
              },
              "targetPbiId": {
                "type": [
                  "string",
                  "null"
                ],
                "default": null
              }
            },
            "required": [
              "issueNumber",
              "commentIds",
              "disposition",
              "draftText",
              "rationale"
            ]
          }
        }
      },
      "required": [
        "drafts"
      ]
    }
  }
]

